<?php
if (PHP_SAPI!=='cli' || !preg_match('/^impe_test_handly_aliados[a-z0-9_]*$/D',getenv('IMPE_DB_NAME')?:'')) exit(2);
require_once __DIR__.'/../config/db_connection.php';
require_once __DIR__.'/../app/services/AliadoRegistroService.php';
require_once __DIR__.'/../app/models/FormularioRegistroModel.php';
require_once __DIR__.'/../app/models/ProspectoModel.php';
require_once __DIR__.'/../app/models/AliadoModel.php';
require_once __DIR__.'/../app/models/CrearConvocatoriaModel.php';
require_once __DIR__.'/../app/models/AliadoInternacionalModel.php';
$db=(new Database())->connect(false);
$db->query("SET SESSION sql_mode='STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,NO_ENGINE_SUBSTITUTION'");
$s=new AliadoRegistroService($db); $form=new FormularioRegistroModel(); $checks=0;
function check($ok,$msg) { global $checks; if(!$ok) throw new RuntimeException($msg); $checks++; echo "OK $msg\n"; }
function rejects(callable $fn,$msg) { try {$fn();} catch(DomainException $e) {check(true,$msg);return;} throw new RuntimeException('ACEPTO: '.$msg); }
function cc() { $_SESSION=['usuario_id'=>2,'rol_id'=>4,'rol'=>'Cuenta Clave','permisos'=>['aliados.crear_manual','aliados.editar_manual','aliados.gestionar_programas']]; }
function marketing() { $_SESSION=['usuario_id'=>4,'rol_id'=>5,'rol'=>'Marketing','permisos'=>['formularios_aliados.gestionar_enlaces']]; }
cc();
$datos=['nombre_entidad'=>'Aliado Regional','tipo_entidad'=>'INSTITUCION','estado_id'=>1,'municipio_id'=>1,'contacto_nombre'=>'Persona de prueba','correo_contacto'=>'contacto@example.test','programas'=>['bachillerato-286','ingles']];
rejects(fn()=>$s->guardarManual(array_replace($datos,['estado_id'=>2,'municipio_id'=>2])),'fuera de territorio');
rejects(fn()=>$s->guardarManual(array_replace($datos,['estado_id'=>99])),'estado inexistente');
rejects(fn()=>$s->guardarManual(array_replace($datos,['municipio_id'=>2])),'municipio de otro estado');
rejects(fn()=>$s->guardarManual(array_replace($datos,['programas'=>['inventado']])),'programa inexistente');
rejects(fn()=>$s->guardarManual(array_replace($datos,['programas'=>[]])),'programas vacíos');
rejects(fn()=>$s->guardarManual(array_replace($datos,['nombre_entidad'=>'Instituto Existente'])),'duplicado institucional');
$id=$s->guardarManual($datos); check($id>0,'crear manual');
check((int)$db->query('SELECT COUNT(*) n FROM seguimientos_vinculacion')->fetch_assoc()['n']===1,'sin expedientes ficticios');
rejects(fn()=>$s->guardarManual(array_replace($datos,['nombre_entidad'=>'  aliado   regional  '])),'duplicado normalizado');
$detalle=$s->detalle('manual',$id); check(count($detalle['programas'])===2 && $detalle['url']==='','programas múltiples y token oculto a Cuenta Clave');
$list=(new AliadoModel())->obtenerListado(2,false,['estado_id'=>1]);
check(count($list)===2,'directorio coexisten manual e institucional');
check(count(array_filter($list,fn($r)=>!empty($r['convenio_formalizado_at'])))===1,'manual no formalizado');
check(count((new AliadoModel())->obtenerListado(2,false,['estado_id'=>1,'buscar'=>'regional']))===1,'búsqueda manual');
check(count($s->resumenManuales([1]))===1,'resumen territorial');
check((int)$s->municipiosTerritoriales(2,false,[1])[0]['total']===1,'municipios compartidos no se cuentan doble');
$s->configurar('institucional',10,['ingles']); check($s->detalle('institucional',10)['programas']===['ingles'],'programas institucionales');
$s->guardarManual(array_replace($datos,['id'=>$id,'notas'=>'Edición conservada']));
check($s->detalle('manual',$id)['origen']['notas']==='Edición conservada','edición transaccional');
$legacy=$db->query("SELECT token FROM formulario_aliados WHERE slug='handly-lenguaje-center'")->fetch_assoc()['token'];
rejects(fn()=>$s->enlace('manual',$id,'generar'),'Cuenta Clave no genera enlaces Marketing');
$_SESSION['rol_id']=1; rejects(fn()=>$s->guardarManual($datos),'Admin no recibe operación por herencia');
marketing();
$link=$s->enlace('manual',$id,'generar'); $same=$s->enlace('manual',$id,'generar');
check($link['url']===$same['url'],'enlace estable idempotente');
parse_str(parse_url($link['url'],PHP_URL_QUERY),$url); $token=$url['aliado'];
check($url['action']==='registro' && strlen($token)===64,'URL Registro token criptográfico');
check((int)$db->query("SELECT activo FROM formulario_aliados WHERE slug='registro-manual-$id'")->fetch_assoc()['activo']===0,'rollback a lector antiguo no habilita Inscripción');
$convenios=(new CrearConvocatoriaModel())->listarConveniosAliados();
check(count($convenios)===2,'Marketing ambos orígenes');
check(array_sum(array_column($convenios,'tiene_convocatoria'))===0,'enlace no crea convocatoria');
$externos=(new AliadoInternacionalModel($db))->obtenerAliados();
check(count($externos)===1 && $externos[0]['slug']==='handly-lenguaje-center','no contamina aliados internacionales');
rejects(fn()=>$form->aliadoExclusivo($token),'nuevo Registro no habilita Inscripción');
check(count($form->aliadoExclusivo($legacy)['programas'])===2,'Handly Inscripción intacta');
check(count($form->aliadoExclusivo($legacy,'registro')['programas'])===2,'Handly Registro intacto');
$submission=['nombre'=>'Ana','apellido'=>'Prueba','fecha_nacimiento'=>'1990-01-01','movil'=>'7771234567','correo'=>'ana@example.test','perfil_interes'=>'Bachillerato 286','lugar_laboras'=>'','cargo_puesto'=>'','estado_id'=>1,'municipio_id'=>1,'creado_por'=>null,'origen'=>'PUBLICO','aliado_token'=>$token];
$first=$form->guardar($submission); check($first===$form->guardar($submission),'duplicado idempotente');
rejects(fn()=>$form->guardar(array_replace($submission,['perfil_interes'=>'Titulación por experiencia laboral'])),'programa ajeno backend');
rejects(fn()=>$form->guardar(array_replace($submission,['municipio_id'=>2])),'municipio adulterado backend');
$s->enlace('manual',$id,'deshabilitar'); check(!$s->enlace('manual',$id,'generar')['habilitado'],'generar de nuevo no reactiva captura deshabilitada'); rejects(fn()=>$form->guardar($submission),'captura deshabilitada');
$s->enlace('manual',$id,'habilitar'); check($form->guardar($submission)===$first,'rehabilitar conserva token y reenvío');
cc(); $s->configurar('manual',$id,['ingles']);
rejects(fn()=>$form->guardar($submission),'programa retirado no se acepta');
check($db->query('SELECT perfil_interes FROM formulario_registros WHERE id='.$first)->fetch_assoc()['perfil_interes']==='Bachillerato 286','programa histórico conservado');
$db->query("UPDATE formulario_programas SET activo=0 WHERE codigo='ingles'");
rejects(fn()=>$form->guardar(array_replace($submission,['perfil_interes'=>'Inglés'])),'programa inactivo backend');
$db->query("UPDATE formulario_programas SET activo=1 WHERE codigo='ingles'");
foreach(['','no-valido',str_repeat('0',64)] as $bad) rejects(fn()=>$form->aliadoExclusivo($bad,'registro'),'token inválido');
$general=$submission; unset($general['aliado_token']); $general['correo']='general@example.test'; $generalId=$form->guardar($general);
$inscripcion=$submission; $inscripcion['aliado_token']=$legacy; $inscripcion['perfil_interes']='Bachillerato General'; $inscripcion['origen']='PUBLICO_INSCRIPCION'; $form->guardar($inscripcion);
$prospectos=new ProspectoModel(); $all=$prospectos->listar(1,25); check($all['total']===2,'Prospectos sin Inscripciones');
$origin=(int)$db->query('SELECT aliado_id FROM formulario_aliado_registro WHERE manual_id='.$id)->fetch_assoc()['aliado_id'];
check($prospectos->listar(1,25,['aliado_id'=>(string)$origin])['total']===1,'filtro origen');
check($prospectos->listar(1,25,['aliado_id'=>'general'])['total']===1,'filtro general');
check($prospectos->listar(2,1)['pagina']===2 && count($prospectos->listar(2,1)['registros'])===1,'paginación y total');
check($prospectos->listar(1,25,['buscar'=>'ZZZ'])['total']===0,'estado vacío');
cc(); $s->desactivar($id); rejects(fn()=>$form->aliadoExclusivo($token,'registro'),'baja lógica impide captura');
check((int)$db->query('SELECT COUNT(*) n FROM formulario_registros')->fetch_assoc()['n']===2,'baja conserva historia');
// Fixture final para navegador: aliado vigente con dos programas, sin alterar tokens.
$db->query('UPDATE aliados_manuales SET activo=1 WHERE id='.$id); $s->configurar('manual',$id,['bachillerato-286','ingles']);
echo "PASS $checks comprobaciones DB\n";
